// Some portions generated by Claude
import type { Graph } from "./graph-types.ts";
import type { LayoutOptions } from "./graph-layout-engine.ts";
import type { GraphLayoutReply, GraphLayoutRequest, GraphLayoutResult } from "./graph-layout-protocol.ts";

type LayoutWorker = Pick<Worker, "postMessage" | "terminate" | "onmessage" | "onerror" | "onmessageerror">;

const createLayoutWorker = (): LayoutWorker =>
  new Worker(new URL("./graph-layout-worker.ts", import.meta.url), { type: "module" });

// Each active job has an exclusive worker. Keep one healthy, completed worker, including its compiled code, for reuse.
let spare: LayoutWorker | null = null;
let owners = 0;
let manuallyRetained = false;
let generation = 0;
let nextRequestId = 1;
let warming: ReturnType<typeof setTimeout> | undefined;
const active = new WeakSet<LayoutWorker>();
const retained = () => owners > 0 || manuallyRetained;

function cancelWarmup() {
  if (warming === undefined) return;
  clearTimeout(warming);
  warming = undefined;
}

function terminate(worker: LayoutWorker) {
  worker.onmessage = worker.onerror = worker.onmessageerror = null;
  worker.terminate();
}

function scheduleWarmup() {
  if (!retained() || spare || warming !== undefined) return;
  const expectedGeneration = generation;
  warming = setTimeout(() => {
    warming = undefined;
    if (expectedGeneration === generation && retained()) ensureSpare();
  }, 0);
}

function park(worker: LayoutWorker) {
  spare = worker;
  worker.onmessage = null;
  const failed = () => {
    // An old idle handler must never terminate a worker which has since been leased to a new job.
    if (spare !== worker) return;
    spare = null;
    terminate(worker);
    // A startup/module-loading failure can persist. Retry only on the next explicit retain or calculation;
    // an idle failure must not create an unbounded zero-delay worker construction loop.
  };
  worker.onerror = worker.onmessageerror = failed;
}

function ensureSpare() {
  if (!retained() || spare || typeof Worker === "undefined") return;
  try {
    park(createLayoutWorker());
  } catch {
    // Prewarming is optional. Starting a requested calculation reports constructor failures to its caller.
  }
}

function releaseUnusedPool() {
  if (retained()) return;
  generation++;
  cancelWarmup();
  if (spare) terminate(spare);
  spare = null;
  // Active jobs still belong to their callers. Their old generation prevents them from repopulating this pool.
}

/** Keep a ready worker while an explorer is mounted. The returned owner handle can be released only once. */
export function retainGraphLayoutWorker(): () => void {
  owners++;
  ensureSpare();
  let released = false;
  return () => {
    if (released) return;
    released = true;
    owners--;
    releaseUnusedPool();
  };
}

/** Explicit prewarming for callers without a mount owner; repeated calls retain the same spare until release. */
export function warmGraphLayoutWorker() {
  manuallyRetained = true;
  ensureSpare();
}

/** Release explicit prewarming. Mounted explorers keep their own ownership until their handles are released. */
export function releaseGraphLayoutWorker() {
  manuallyRetained = false;
  releaseUnusedPool();
}

/**
 * One worker per active calculation. A successful default worker returns to the pool; cancellation and errors stop
 * its CPU work by terminating it. Injected factories remain exclusive, one-shot workers and never enter the pool.
 */
export function startGraphLayout(
  graph: Graph,
  options: LayoutOptions = {},
  createWorker: () => LayoutWorker = createLayoutWorker,
) {
  const pooled = createWorker === createLayoutWorker;
  if (pooled) {
    // A direct, unmounted caller can release this implicit ownership with releaseGraphLayoutWorker().
    if (!retained()) manuallyRetained = true;
    cancelWarmup();
  }
  const workerGeneration = generation;
  const requestId = nextRequestId++;
  let worker: LayoutWorker | undefined;
  let settled = false;
  let rejectJob: (reason: Error) => void = () => {};
  const cleanup = (success: boolean) => {
    const finished = worker;
    worker = undefined;
    if (!finished) return;
    finished.onmessage = finished.onerror = finished.onmessageerror = null;
    active.delete(finished);
    if (success && pooled && workerGeneration === generation && retained() && !spare) park(finished);
    else terminate(finished);
    if (pooled && workerGeneration === generation) scheduleWarmup();
  };
  const promise = new Promise<GraphLayoutResult>((resolve, reject) => {
    rejectJob = reject;
    const fail = (error: Error) => {
      if (settled) return;
      settled = true;
      cleanup(false);
      reject(error);
    };
    try {
      const acquired = pooled && spare ? spare : createWorker();
      if (active.has(acquired) || (!pooled && acquired === spare)) {
        throw new Error("The graph layout worker is already owned by another calculation or the pool.");
      }
      if (pooled && acquired === spare) spare = null;
      worker = acquired;
      active.add(worker);
      worker.onmessage = (event: MessageEvent<GraphLayoutReply>) => {
        if (settled) return;
        const data = event.data;
        if (!data || typeof data !== "object") {
          fail(new Error("The graph layout worker returned an invalid reply."));
          return;
        }
        if ("requestId" in data) {
          if (data.requestId !== requestId) return;
        } else if (pooled) {
          fail(new Error("The graph layout worker returned a reply without its request ID."));
          return;
        }
        // Only one-shot injected workers accept the previous ID-less reply format: no subsequent job can see it.
        if ("error" in data) {
          fail(new Error(String(data.error)));
          return;
        }
        if (!("result" in data) || !data.result || !(data.result.positions instanceof Map) || !(data.result.bends instanceof Map)) {
          fail(new Error("The graph layout worker returned an invalid result."));
          return;
        }
        settled = true;
        cleanup(true);
        resolve(data.result);
      };
      worker.onerror = () => fail(new Error("The graph layout worker failed."));
      worker.onmessageerror = () => fail(new Error("The graph layout result could not be read."));
      const request: GraphLayoutRequest = { requestId, graph, options };
      worker.postMessage(request);
    } catch (error) {
      fail(error instanceof Error ? error : new Error(String(error)));
    }
  });
  return {
    promise,
    cancel() {
      if (settled) return;
      settled = true;
      cleanup(false);
      rejectJob(new DOMException("Layout cancelled", "AbortError"));
    },
  };
}
